/* Private review cycle, notifications and account requests. Server RPCs enforce ownership. */
window.SaiStudentCare=(()=>{
 let stories=[],activeUser='',generation=0,lastBadge=0;
 const labels={pending:'تجربتك قيد المراجعة',published:'تم نشر تجربتك',rejected:'تجربتك تحتاج تعديلًا'},requestKinds={help:'مساعدة',correction:'تصحيح بيانات',deletion:'طلب حذف البيانات'};
 const stamp=value=>new Intl.DateTimeFormat(document.documentElement.lang==='en'?'en-GB':'ar-SA-u-ca-gregory',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
 function badge(count){const visible=!!user;$('#notifications-link').hidden=!visible;const n=$('#notifications-count');n.hidden=!count;n.textContent=count>99?'99+':count;$('#profile-link').classList.toggle('has-unread',visible&&count>0);let hint=$('#profile-unread-hint');if(!hint){hint=document.createElement('span');hint.id='profile-unread-hint';hint.className='sr-only';$('#profile-link').append(hint);}hint.textContent='تنبيهات غير مقروءة';hint.hidden=!visible||!count;const profileBadge=$('#profile-notifications-count');if(profileBadge){profileBadge.textContent=count?' ('+count+')':'';}}
 async function refreshBadge(force=false){if(!user)return;if(!force&&Date.now()-lastBadge<30000)return;lastBadge=Date.now();const owner=user.id,version=accountVersion;try{const data=await api.notifications();if(user?.id===owner&&version===accountVersion)badge(Number(data.unread)||0);}catch{}}
 function syncUser(){const id=user?.id||'';if(id===activeUser){if(!id)badge(0);return;}activeUser=id;generation++;stories=[];lastBadge=0;badge(0);if(id)refreshBadge(true);else{$('#notifications-content').replaceChildren();$('#support-content').replaceChildren();}}
 function experienceCard(e){return `<details class="profile-experience"><summary><span class="profile-experience-title">${esc(e.title||'تجربتي')}</span><span class="profile-experience-meta"><span class="badge">${esc(e.topic||'تجربة أخرى')}</span><span class="badge profile-experience-status">${esc({pending:'قيد المراجعة',published:'منشورة',rejected:'تحتاج تعديلًا'}[e.status]||'قيد المراجعة')}</span></span><span class="profile-experience-toggle" aria-hidden="true">+</span></summary><div class="profile-experience-body">${e.review_note?`<aside class="review-note"><strong>ملاحظة المراجعة</strong>${paragraphs(e.review_note)}</aside>`:''}${window.SaiExperienceLinks.summary(e)}<div class="experience-detail-copy">${paragraphs(e.body)}</div>${e.status==='rejected'?`<button class="button outline" type="button" data-revise-story="${esc(e.id)}">تعديل وإعادة إرسال</button>`:''}</div></details>`;}
 function mountProfile(rows){stories=rows;refreshBadge();}
 function revise(id){const row=stories.find(e=>e.id===id);if(!row||row.status!=='rejected'||!user)return;const owner=user.id,version=accountVersion;
  show('تعديل التجربة',`${row.review_note?'<aside class="review-note"><strong>ملاحظة المراجعة</strong>'+paragraphs(row.review_note)+'</aside>':''}<form id="revise-story-form" class="platform-form"><label>عنوان التجربة<input name="title" maxlength="120" value="${esc(row.title||'')}"></label><label>موضوع التجربة<select name="topic" required>${experienceOptions(experienceTopics,row.topic,'اختر موضوع التجربة')}</select></label><label>المجال<select name="field" required>${experienceOptions(experienceFields(),row.field,'اختر المجال')}</select></label>${window.SaiExperienceLinks.field(row.related_id?row.related_kind+':'+row.related_id:'',row)}<label>نص التجربة<textarea name="body" minlength="30" maxlength="6000" rows="8" required>${esc(row.body)}</textarea></label><label class="check-label"><input type="checkbox" required>أوافق على إرسال تجربتي للمراجعة قبل النشر.</label><p id="revise-story-feedback" role="status" hidden></p><button class="button" type="submit">إعادة الإرسال للمراجعة</button></form>`,true);
  $('#revise-story-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const payload=Object.fromEntries(new FormData(form));await formRequest(form,'#revise-story-feedback',async current=>{await api.resubmitExperience(id,row.revision,{...payload,...window.SaiExperienceLinks.values(payload.related_content)});if(user?.id!==owner||version!==accountVersion)return;if(current())dialog.close();notice('أعيد إرسال تجربتك للمراجعة.');refreshBadge(true);if(location.hash==='#profile')await loadProfile();});};
 }
 async function notifications(){if(!user)return;const token=++generation,owner=user.id,version=accountVersion,host=$('#notifications-content');host.innerHTML='<p role="status">جارٍ تحميل التنبيهات…</p>';
  try{const data=await api.notifications();if(token!==generation||version!==accountVersion||owner!==user?.id)return;badge(Number(data.unread)||0);host.innerHTML=`<div class="care-toolbar"><p class="muted">آخر 50 تنبيهًا عن تجاربك والفرص المناسبة لاهتماماتك.</p>${data.unread?'<button class="button outline" type="button" data-read-all>تحديد الكل كمقروء</button>':''}</div><p id="notifications-feedback" role="status" hidden></p><div class="care-list">${data.items.map(n=>`<article class="care-card ${n.read_at?'':'unread'}"><h2>${n.kind==='opportunity'?'فرصة جديدة تناسب اهتماماتك':labels[n.status]||'تحديث التجربة'}</h2><strong>${esc(n.title||'تجربتي')}</strong>${n.note?paragraphs(n.note):''}<time>${esc(stamp(n.created_at))}</time><div class="care-toolbar">${n.kind==='opportunity'?`<a class="text-link" href="#opportunities/${encodeURIComponent(n.target_id)}">عرض الفرصة</a>`:'<a class="text-link" href="#profile">فتح تجاربي</a>'}${n.read_at?'':`<button class="text-link" data-read-notification="${esc(n.id)}" type="button">تحديد كمقروء</button>`}</div></article>`).join('')||'<p class="empty">لا توجد تنبيهات بعد.</p>'}</div>`;
   host.onclick=async event=>{const button=event.target.closest('[data-read-notification],[data-read-all]');if(!button)return;button.disabled=true;try{await api.readNotifications(button.dataset.readNotification||null,button.hasAttribute('data-read-all')?data.checked_at:null);if(owner===user?.id&&version===accountVersion)await notifications();}catch(error){if(host.isConnected&&version===accountVersion)status('#notifications-feedback',error.message,true);}finally{button.disabled=false;}};
  }catch{if(token===generation&&version===accountVersion)host.innerHTML='<p>تعذّر تحميل التنبيهات.</p><button type="button" class="text-link" data-notifications-retry>إعادة المحاولة</button>';}
 }
 async function support(){if(!user)return;const token=++generation,owner=user.id,version=accountVersion,host=$('#support-content');host.innerHTML='<p role="status">جارٍ تحميل طلباتك…</p>';
  try{const rows=await api.accountRequests();if(token!==generation||owner!==user?.id||version!==accountVersion)return;host.innerHTML=`<form id="account-request-form" class="platform-form"><p>يصل طلبك بشكل خاص إلى مالك سعي. لا ترسل كلمة مرور أو رمز تحقق.</p><label>نوع الطلب<select name="kind" required>${Object.entries(requestKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>تفاصيل الطلب<textarea name="message" minlength="5" maxlength="2000" rows="5" required></textarea></label><p class="muted">طلب الحذف يُراجع يدويًا، ولا يحذف الحساب فور الإرسال.</p><p id="account-request-feedback" role="status" hidden></p><button type="submit" class="button">إرسال الطلب</button></form><h2 class="care-subheading">طلباتي السابقة</h2><div class="care-list">${rows.map(row=>`<article class="care-card"><h3>${requestKinds[row.kind]}</h3><span class="badge">${row.status==='open'?'مفتوح':'مغلق'}</span>${paragraphs(row.message)}${row.response?'<aside class="review-note"><strong>رد المالك</strong>'+paragraphs(row.response)+'</aside>':''}<time>${esc(stamp(row.created_at))}</time></article>`).join('')||'<p>لم ترسل طلبًا بعد.</p>'}</div>`;
   $('#account-request-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const fd=new FormData(form);await formRequest(form,'#account-request-feedback',async current=>{await api.submitAccountRequest(fd.get('kind'),fd.get('message'));if(!current())return;await support();notice('تم إرسال طلبك إلى المالك.');});};
  }catch{if(token===generation&&version===accountVersion)host.innerHTML='<p>تعذّر تحميل طلباتك.</p><button class="text-link" type="button" data-support-retry>إعادة المحاولة</button>';}
 }
 async function mountOwner(){if(user?.role!=='admin')return;const version=accountVersion,section=document.createElement('section');$('#owner-account-requests')?.remove();section.id='owner-account-requests';section.className='owner-section';section.innerHTML='<h2>طلبات الحسابات والمساعدة</h2><p role="status">جارٍ تحميل الطلبات…</p>';$('#admin-content').append(section);
  try{const rows=await api.ownerAccountRequests();if(user?.role!=='admin'||version!==accountVersion||!section.isConnected)return;section.innerHTML='<h2>طلبات الحسابات والمساعدة</h2><p class="muted">آخر 200 طلب؛ الطلبات المفتوحة أولًا.</p><label class="owner-search">حالة الطلب<select id="account-request-filter"><option value="open">مفتوح</option><option value="closed">مغلق</option><option value="all">جميع الطلبات</option></select></label><div id="owner-account-request-list" class="owner-list"></div>';
   const render=()=>{const state=$('#account-request-filter').value,list=$('#owner-account-request-list');list.innerHTML=rows.filter(row=>state==='all'||row.status===state).map(row=>`<article class="owner-row"><div><h3>${requestKinds[row.kind]}</h3><p>${esc(row.name)}</p><span class="badge">${row.status==='open'?'مفتوح':'مغلق'}</span></div><button class="button outline" data-account-reply="${esc(row.id)}" type="button">قراءة والرد</button></article>`).join('')||'<p>لا توجد طلبات بهذه الحالة.</p>';window.SaiOwnerLists.limit(list);};$('#account-request-filter').onchange=render;render();section.onclick=event=>{const id=event.target.closest('[data-account-reply]')?.dataset.accountReply,row=rows.find(r=>r.id===id);if(!row||user?.role!=='admin')return;
    show('الرد على الطلب',`<p>${esc(row.name)}</p>${paragraphs(row.message)}${row.kind==='deletion'?`<p class="muted">الرد وإغلاق الطلب لا يحذفان الحساب. بعد التحقق من صاحب الطلب، ينفّذ المالك الحذف من Supabase.</p><label class="platform-form">معرّف الحساب<input readonly value="${esc(row.account_id)}"></label>`:''}<form id="account-reply-form" class="platform-form"><label>الرد<textarea name="response" maxlength="1500" rows="5">${esc(row.response||'')}</textarea></label><label>حالة الطلب<select name="decision"><option value="open" ${row.status==='open'?'selected':''}>مفتوح</option><option value="closed" ${row.status==='closed'?'selected':''}>مغلق</option></select></label><p id="account-reply-feedback" role="status" hidden></p><button type="submit" class="button">حفظ الرد</button></form>`,true);
    $('#account-reply-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,fd=new FormData(form);await formRequest(form,'#account-reply-feedback',async current=>{await api.ownerReplyAccountRequest(row.id,row.revision,fd.get('response'),fd.get('decision'));if(!current())return;dialog.close();await mountOwner();notice('تم حفظ الرد.');});};
   };
  }catch{if(section.isConnected&&version===accountVersion)section.innerHTML='<h2>طلبات الحسابات والمساعدة</h2><p>تعذّر تحميل الطلبات.</p><button type="button" class="text-link" data-owner-care-retry>إعادة المحاولة</button>';}
 }
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.reviseStory)revise(button.dataset.reviseStory);if(button.hasAttribute('data-notifications-retry'))notifications();if(button.hasAttribute('data-support-retry'))support();if(button.hasAttribute('data-owner-care-retry'))mountOwner();});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshBadge();});
 setInterval(()=>{if(user&&!document.hidden)refreshBadge();},60000);
 window.addEventListener('sai:signout',()=>{activeUser='';generation++;stories=[];badge(0);$('#notifications-content').replaceChildren();$('#support-content').replaceChildren();});
 return {syncUser,refreshBadge,experienceCard,mountProfile,notifications,support,mountOwner};
})();
